package session

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
)

// Replay reads a session log and renders a human-readable conversation.
func Replay(path string, w io.Writer) error {
	events, err := ReadEvents(path)
	if err != nil {
		return fmt.Errorf("replay: %w", err)
	}

	for _, e := range events {
		switch e.Type {
		case agent.EventLLMRequest:
			var data LLMRequestData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[LLM Request] (%d messages, %d tools)\n", len(data.Messages), len(data.Tools))
			for _, m := range data.Messages {
				switch m.Role {
				case agent.RoleSystem:
					fmt.Fprintf(w, "  [system] %s\n", m.Content)
				case agent.RoleUser:
					fmt.Fprintf(w, "  [user] %s\n", m.Content)
				case agent.RoleAssistant:
					if m.Content != "" {
						fmt.Fprintf(w, "  [assistant] %s\n", m.Content)
					}
					for _, tc := range m.ToolCalls {
						fmt.Fprintf(w, "  [assistant tool_call] %s(%s)\n", tc.Name, compactJSON(tc.Arguments))
					}
				case agent.RoleTool:
					content := m.Content
					if len(content) > 200 {
						content = content[:200] + "...[truncated]"
					}
					fmt.Fprintf(w, "  [tool result] %s\n", strings.ReplaceAll(content, "\n", "\n              "))
				}
			}

		case agent.EventSessionStart:
			var data SessionStartData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "=== Session %s ===\n", e.SessionID)
			fmt.Fprintf(w, "Time: %s\n", e.Timestamp.Format("2006-01-02 15:04:05 UTC"))
			fmt.Fprintf(w, "Provider: %s | Model: %s\n", data.Provider, data.Model)
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			if data.Sticky.KeyPresent || data.Sticky.Assignment != "" || data.Sticky.Reason != "" {
				fmt.Fprintf(w, "Sticky: key=%s assignment=%s",
					routingStickyLabel(data.Sticky.KeyPresent),
					labelOrUnknown(data.Sticky.Assignment))
				if data.Sticky.Reason != "" {
					fmt.Fprintf(w, " reason=%s", data.Sticky.Reason)
				}
				fmt.Fprintln(w)
			}
			if data.Utilization.Source != "" || data.Utilization.Freshness != "" ||
				data.Utilization.ActiveRequests != nil || data.Utilization.QueuedRequests != nil ||
				data.Utilization.MaxConcurrency != nil || data.Utilization.CachePressure != nil {
				fmt.Fprintf(w, "Utilization: source=%s freshness=%s",
					labelOrUnknown(data.Utilization.Source),
					labelOrUnknown(data.Utilization.Freshness))
				if data.Utilization.ActiveRequests != nil {
					fmt.Fprintf(w, " active=%d", *data.Utilization.ActiveRequests)
				}
				if data.Utilization.QueuedRequests != nil {
					fmt.Fprintf(w, " queued=%d", *data.Utilization.QueuedRequests)
				}
				if data.Utilization.MaxConcurrency != nil {
					fmt.Fprintf(w, " max=%d", *data.Utilization.MaxConcurrency)
				}
				if data.Utilization.CachePressure != nil {
					fmt.Fprintf(w, " cache_pressure=%.2f", *data.Utilization.CachePressure)
				}
				fmt.Fprintln(w)
			}
			fmt.Fprintf(w, "Max iterations: %d | Work dir: %s\n", data.MaxIterations, data.WorkDir)
			if data.SystemPrompt != "" {
				fmt.Fprintf(w, "\n[System]\n%s\n", data.SystemPrompt)
			}
			fmt.Fprintf(w, "\n[User]\n%s\n", data.Prompt)

		case agent.EventLLMResponse:
			var data LLMResponseData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[Assistant] (%dms, %d in / %d out tokens",
				data.LatencyMs, data.Usage.Input, data.Usage.Output)
			if data.CostUSD > 0 {
				fmt.Fprintf(w, ", $%.4f", data.CostUSD)
			}
			fmt.Fprintf(w, ")\n")
			if data.Content != "" {
				fmt.Fprintf(w, "%s\n", data.Content)
			}
			if len(data.ToolCalls) > 0 {
				fmt.Fprintf(w, "[%d tool call(s)]\n", len(data.ToolCalls))
			}

		case agent.EventToolCall:
			var data ToolCallData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n  > %s (%dms)\n", data.Tool, data.DurationMs)
			fmt.Fprintf(w, "    Input:  %s\n", compactJSON(data.Input))
			output := data.Output
			if len(output) > 200 {
				output = output[:200] + "...[truncated]"
			}
			fmt.Fprintf(w, "    Output: %s\n", strings.ReplaceAll(output, "\n", "\n            "))
			if data.Error != "" {
				fmt.Fprintf(w, "    Error:  %s\n", data.Error)
			}

		case agent.EventSessionEnd:
			var data SessionEndData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n=== End (%s) ===\n", data.Status)
			if data.Model != "" {
				fmt.Fprintf(w, "Model: %s\n", data.Model)
			}
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			fmt.Fprintf(w, "Duration: %dms | Tokens: %d in / %d out",
				data.DurationMs, data.Tokens.Input, data.Tokens.Output)
			if data.CostUSD == nil || *data.CostUSD < 0 {
				fmt.Fprintf(w, " | Cost: unknown")
			} else if *data.CostUSD > 0 {
				fmt.Fprintf(w, " | Cost: $%.4f", *data.CostUSD)
			} else {
				fmt.Fprintf(w, " | Cost: $0 (local)")
			}
			fmt.Fprintln(w)
			if len(data.Metadata) > 0 {
				fmt.Fprintf(w, "Metadata:")
				for k, v := range data.Metadata {
					fmt.Fprintf(w, " %s=%s", k, v)
				}
				fmt.Fprintln(w)
			}
			if data.Error != "" {
				fmt.Fprintf(w, "Error: %s\n", data.Error)
			}
		}
	}
	return nil
}

func routingStickyLabel(present bool) string {
	if present {
		return "present"
	}
	return "absent"
}

func labelOrUnknown(v string) string {
	if v == "" {
		return "unknown"
	}
	return v
}

func compactJSON(raw json.RawMessage) string {
	var v any
	if json.Unmarshal(raw, &v) != nil {
		return string(raw)
	}
	data, _ := json.Marshal(v)
	return string(data)
}

package session

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	agent "github.com/DocumentDrivenDX/fizeau/internal/core"
)

// UsageOptions configures how session logs are aggregated.
type UsageOptions struct {
	// Since limits the report window. Supported values include today, 7d, 30d,
	// a date range (YYYY-MM-DD..YYYY-MM-DD), or a single start date.
	Since string

	// Now is the reference time for relative windows. Zero means time.Now().
	Now time.Time
}

// UsageWindow describes the active reporting window.
type UsageWindow struct {
	Start time.Time `json:"start"`
	End   time.Time `json:"end"`
}

// Contains reports whether ts falls within the half-open usage window.
func (w UsageWindow) Contains(ts time.Time) bool {
	ts = ts.UTC()
	if !w.Start.IsZero() && ts.Before(w.Start) {
		return false
	}
	if !w.End.IsZero() && !ts.Before(w.End) {
		return false
	}
	return true
}

// UsageRow aggregates usage for one provider/model pair.
type UsageRow struct {
	Provider            string   `json:"provider"`
	Model               string   `json:"model"`
	Sessions            int      `json:"sessions"`
	SuccessSessions     int      `json:"success_sessions"`
	FailedSessions      int      `json:"failed_sessions"`
	InputTokens         int      `json:"input_tokens"`
	OutputTokens        int      `json:"output_tokens"`
	TotalTokens         int      `json:"total_tokens"`
	DurationMs          int64    `json:"duration_ms"`
	KnownCostUSD        *float64 `json:"known_cost_usd"`
	UnknownCostSessions int      `json:"unknown_cost_sessions"`
	CacheReadTokens     int      `json:"cache_read_tokens"`
	CacheWriteTokens    int      `json:"cache_write_tokens"`
}

// SuccessRate returns the fraction of sessions that succeeded (0 if no sessions).
func (r UsageRow) SuccessRate() float64 {
	if r.Sessions == 0 {
		return 0
	}
	return float64(r.SuccessSessions) / float64(r.Sessions)
}

// CostPerSuccess returns the known cost divided by successful sessions,
// or nil if there are no successes or cost is unknown.
func (r UsageRow) CostPerSuccess() *float64 {
	if r.SuccessSessions == 0 || r.KnownCostUSD == nil {
		return nil
	}
	v := *r.KnownCostUSD / float64(r.SuccessSessions)
	return &v
}

// InputTokensPerSecond returns the average input-token throughput.
func (r UsageRow) InputTokensPerSecond() float64 {
	if r.DurationMs <= 0 {
		return 0
	}
	return float64(r.InputTokens) / (float64(r.DurationMs) / 1000)
}

// OutputTokensPerSecond returns the average output-token throughput.
func (r UsageRow) OutputTokensPerSecond() float64 {
	if r.DurationMs <= 0 {
		return 0
	}
	return float64(r.OutputTokens) / (float64(r.DurationMs) / 1000)
}

// CacheHitRate returns the fraction of input tokens served from cache (0..1).
func (r UsageRow) CacheHitRate() float64 {
	total := r.InputTokens + r.CacheReadTokens + r.CacheWriteTokens
	if total == 0 {
		return 0
	}
	return float64(r.CacheReadTokens) / float64(total)
}

// UsageReport is the aggregate output for a session log scan.
type UsageReport struct {
	Window *UsageWindow `json:"window,omitempty"`
	Rows   []UsageRow   `json:"rows"`
	Totals UsageRow     `json:"totals"`
}

type usageSession struct {
	Provider    string
	Model       string
	StartedAt   time.Time
	EndedAt     time.Time
	DurationMs  int64
	Tokens      agent.TokenUsage
	KnownCost   float64
	UnknownCost bool
	Status      agent.Status
}

// AggregateUsage scans JSONL session logs in logDir and aggregates token and
// cost totals by provider/model.
func AggregateUsage(logDir string, opts UsageOptions) (*UsageReport, error) {
	now := opts.Now.UTC()
	if now.IsZero() {
		now = time.Now().UTC()
	}

	window, err := ParseUsageWindow(opts.Since, now)
	if err != nil {
		return nil, err
	}

	entries, err := os.ReadDir(logDir)
	if err != nil {
		if os.IsNotExist(err) {
			return &UsageReport{Window: window}, nil
		}
		return nil, fmt.Errorf("usage: reading session log dir: %w", err)
	}

	rows := make(map[string]*UsageRow)
	report := &UsageReport{Window: window}

	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".jsonl" {
			continue
		}

		path := filepath.Join(logDir, entry.Name())
		events, err := ReadEvents(path)
		if err != nil {
			return nil, fmt.Errorf("usage: reading %s: %w", path, err)
		}

		session, ok := summarizeUsageSession(events)
		if !ok {
			continue
		}
		if window != nil && !window.Contains(session.StartedAt) {
			continue
		}

		key := session.Provider + "\x00" + session.Model
		row, ok := rows[key]
		if !ok {
			row = &UsageRow{Provider: session.Provider, Model: session.Model}
			rows[key] = row
		}

		row.Sessions++
		if session.Status == agent.StatusSuccess {
			row.SuccessSessions++
		} else {
			row.FailedSessions++
		}
		row.InputTokens += session.Tokens.Input
		row.OutputTokens += session.Tokens.Output
		row.TotalTokens += effectiveTotalTokens(session.Tokens)
		row.DurationMs += session.DurationMs
		row.CacheReadTokens += session.Tokens.CacheRead
		row.CacheWriteTokens += session.Tokens.CacheWrite
		accumulateUsageCost(row, session)

		report.Totals.Sessions++
		if session.Status == agent.StatusSuccess {
			report.Totals.SuccessSessions++
		} else {
			report.Totals.FailedSessions++
		}
		report.Totals.InputTokens += session.Tokens.Input
		report.Totals.OutputTokens += session.Tokens.Output
		report.Totals.TotalTokens += effectiveTotalTokens(session.Tokens)
		report.Totals.DurationMs += session.DurationMs
		report.Totals.CacheReadTokens += session.Tokens.CacheRead
		report.Totals.CacheWriteTokens += session.Tokens.CacheWrite
		accumulateUsageCost(&report.Totals, session)
	}

	report.Rows = make([]UsageRow, 0, len(rows))
	for _, row := range rows {
		report.Rows = append(report.Rows, *row)
	}

	sort.Slice(report.Rows, func(i, j int) bool {
		if report.Rows[i].Provider != report.Rows[j].Provider {
			return report.Rows[i].Provider < report.Rows[j].Provider
		}
		return report.Rows[i].Model < report.Rows[j].Model
	})

	return report, nil
}

func accumulateUsageCost(row *UsageRow, session usageSession) {
	if session.UnknownCost {
		row.UnknownCostSessions++
		row.KnownCostUSD = nil
		return
	}
	if row.UnknownCostSessions > 0 {
		return
	}
	if row.KnownCostUSD == nil {
		row.KnownCostUSD = new(float64)
	}
	*row.KnownCostUSD += session.KnownCost
}

